  <script>
    // Initialize Lucide icons
    lucide.createIcons();

    // Stats counter animation
    function animateCounter(element, target, duration = 2000) {
      const start = 0;
      const startTime = performance.now();

      function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const easeOut = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(start + (target - start) * easeOut);
        element.textContent = current.toLocaleString();

        if (progress < 1) {
          requestAnimationFrame(update);
        } else {
          element.textContent = target.toLocaleString();
        }
      }

      requestAnimationFrame(update);
    }

    // Intersection Observer for stats
    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const statNumbers = entry.target.querySelectorAll('.stat-number');
          statNumbers.forEach((el, index) => {
            setTimeout(() => {
              el.classList.add('visible');
              animateCounter(el, parseInt(el.dataset.target));
            }, index * 150);
          });
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    const statsSection = document.getElementById('stats');
    if (statsSection) {
      statsObserver.observe(statsSection);
    }

    // Search tabs
    const searchTabs = document.querySelectorAll('.search-tab');
    const tabContents = document.querySelectorAll('.tab-content');

    searchTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        const targetTab = tab.dataset.tab;

        searchTabs.forEach(t => {
          t.classList.remove('active');
          t.classList.add('text-gray-500');
        });
        tab.classList.add('active');
        tab.classList.remove('text-gray-500');

        tabContents.forEach(content => {
          content.classList.remove('visible');
          content.classList.add('hidden');
        });

        const activeContent = document.getElementById(`${targetTab}-content`);
        if (activeContent) {
          activeContent.classList.remove('hidden');
          activeContent.classList.add('visible');
        }
      });
    });

    // Filter pills
    const filterPills = document.querySelectorAll('.filter-pill');

    filterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        filterPills.forEach(p => {
          if (p.dataset.filter !== 'all') {
            p.classList.remove('active', 'bg-primary', 'text-white');
            p.classList.add('bg-white', 'text-gray-600', 'border', 'border-gray-200');
          }
        });
        pill.classList.add('active');
        pill.classList.remove('bg-white', 'text-gray-600', 'border', 'border-gray-200');
        pill.classList.add('bg-primary', 'text-white');
      });
    });

    // Flows toggle
    const flowsToggles = document.querySelectorAll('.flows-toggle');
    const flowsContents = document.querySelectorAll('.flows-content');

    flowsToggles.forEach(toggle => {
      toggle.addEventListener('click', () => {
        const targetFlow = toggle.dataset.flow;

        flowsToggles.forEach(t => {
          t.classList.remove('active');
          t.classList.add('text-gray-500');
        });
        toggle.classList.add('active');
        toggle.classList.remove('text-gray-500');

        flowsContents.forEach(content => {
          content.classList.remove('visible');
          content.classList.add('hidden');
        });

        const activeContent = document.getElementById(`${targetFlow}-content`);
        if (activeContent) {
          activeContent.classList.remove('hidden');
          activeContent.classList.add('visible');
        }
      });
    });
  </script>
